import{_ as a,o as t,c as o,b6 as n,nF as i,nG as r,nH as s,aU as l,nI as h}from"./chunks/framework.COUcLbTA.js";const w=JSON.parse('{"title":"During Finals Week, I Secretly Built a \\"Campus Xianyu\\" with AI","description":"The story of a sophomore student who built a campus secondhand marketplace demo during finals week.","frontmatter":{"title":"During Finals Week, I Secretly Built a \\"Campus Xianyu\\" with AI","description":"The story of a sophomore student who built a campus secondhand marketplace demo during finals week."},"headers":[],"relativePath":"en/vibe-stories/story-2.md","filePath":"en/vibe-stories/story-2.md"}'),d={name:"en/vibe-stories/story-2.md"};function u(m,e,c,p,g,f){return t(),o("div",null,[...e[0]||(e[0]=[n('<h1 id="during-finals-week-i-secretly-built-a-campus-xianyu-with-ai" tabindex="-1">During Finals Week, I Secretly Built a &quot;Campus Xianyu&quot; with AI <a class="header-anchor" href="#during-finals-week-i-secretly-built-a-campus-xianyu-with-ai" aria-label="Permalink to “During Finals Week, I Secretly Built a &quot;Campus Xianyu&quot; with AI”">​</a></h1><p style="font-size:52px;line-height:1;margin:0 0 12px;">🎓</p><p><strong>Narrated by: A sophomore student</strong></p><h2 id="_01-mao-xiaolv-s-3-hour-miracle-and-my-overheated-brain" tabindex="-1">01 Mao Xiaolv&#39;s &quot;3-Hour Miracle&quot; and My Overheated Brain <a class="header-anchor" href="#_01-mao-xiaolv-s-3-hour-miracle-and-my-overheated-brain" aria-label="Permalink to “01 Mao Xiaolv&#39;s &quot;3-Hour Miracle&quot; and My Overheated Brain”">​</a></h2><p>&quot;Help me test it. Try chatting with it.&quot;</p><p>&quot;That&#39;s amazing. Finals are coming up and you&#39;re still staying up late coding. Go study already.&quot;</p><p>&quot;It only took 3 hours.&quot;</p><p>During finals week in January 2026, while I was buried in review, I suddenly got a link from a technical genius friend named Mao Xiaolv. It was an AI chat website. It already had features like scheduling and anime tracking, and the interface looked surprisingly polished.</p><p>Three hours? I stared at the screen and felt like my brain was overheating. Once again, this guy had reset my understanding of what &quot;fast&quot; meant. Then he sent me a pile of materials. I opened them and realized that while I recognized every single character, the full sentences might as well have been written in another language. I wanted to ask him, but I was afraid of exposing how much of a beginner I was. So I ended up doing this: he threw jargon at me, I quietly pasted it into Doubao, waited for an explanation, and then cautiously replied to him. My learning process had turned from &quot;person-to-person&quot; into &quot;person-to-AI-to-person.&quot;</p><p><img src="'+i+'" alt="The first website Mao Xiaolv built"></p><h2 id="_02-on-my-first-day-in-the-group-chat-i-chose-silence" tabindex="-1">02 On My First Day in the Group Chat, I Chose Silence <a class="header-anchor" href="#_02-on-my-first-day-in-the-group-chat-i-chose-silence" aria-label="Permalink to “02 On My First Day in the Group Chat, I Chose Silence”">​</a></h2><p>The group-based learning program started in January, and Mao Xiaolv pulled me into a big learning chat. The opening round was self-introductions: &quot;many years of development experience,&quot; &quot;currently at a major tech company,&quot; and so on. I stared at everyone else&#39;s intros, paused with my fingers on the keyboard for a few seconds, and then deleted the two lines I had just typed. I sighed to myself: &quot;When experts are sparring, maybe the fool should keep quiet.&quot;</p><p>Later, Mao Xiaolv, another new friend, and I formed a smaller group of three, and I finally started to relax. The atmosphere in that group made me especially happy: nobody cared how old you were, what job you had, or whether you were impressive. If a problem came up, we just talked about it as equals and figured it out together. Most of the time everyone was busy and quiet, but you could still feel that people were putting in effort behind the scenes. It was strangely grounding. In school, I rarely experienced this feeling of not being defined by labels and simply moving forward with others because of shared interest.</p><p><img src="'+r+'" alt="A quiet evening of figuring things out alone"></p><h2 id="_03-slacking-off-during-finals-actually-made-me-learn-harder" tabindex="-1">03 &quot;Slacking Off&quot; During Finals Actually Made Me Learn Harder <a class="header-anchor" href="#_03-slacking-off-during-finals-actually-made-me-learn-harder" aria-label="Permalink to “03 &quot;Slacking Off&quot; During Finals Actually Made Me Learn Harder”">​</a></h2><p>During this learning stretch, I felt much less tension and anxiety than before. Even while preparing for finals, if my daily progress check-ins were slow, nobody rushed me or blamed me. Everything was on me, and that freedom somehow made me more motivated.</p><p>It felt very different from the standard-answer learning atmosphere of high school and college. This kind of autonomy actually made me want to work harder.</p><p>Each day&#39;s task check-in felt like leveling up in a game. Learning became more active, and I learned much more because of it.</p><p><img src="'+s+'" alt="Studying during finals week"></p><h2 id="_04-in-a-moment-of-excitement-i-dug-myself-a-huge-hole" tabindex="-1">04 In a Moment of Excitement, I Dug Myself a Huge Hole <a class="header-anchor" href="#_04-in-a-moment-of-excitement-i-dug-myself-a-huge-hole" aria-label="Permalink to “04 In a Moment of Excitement, I Dug Myself a Huge Hole”">​</a></h2><p>Before I knew it, winter break was approaching, and this round of learning was almost over. Before the graduation livestream showcase, the teacher asked me whether I wanted to demo a product.</p><p>&quot;Yes!&quot;</p><p>I answered almost reflexively, even though I had no idea what I was going to build.</p><p>As I scrolled through the dorm and campus group chats full of secondhand listings, a direction started to form. Campus secondhand trading had always existed inside temporary chat groups. People usually arranged to meet at a dorm building or cafeteria, and almost nobody bothered to use a bigger marketplace app. So I started thinking: what if there were a secondhand platform just for campus users? It could show listings from your own school or nearby schools more accurately, and it would naturally come with a bit more trust, reducing the fear of being scammed.</p><p>Once the idea clicked, I threw myself into my first real AI product design. The page design came pretty smoothly: a product browsing page as soon as you enter, a search bar on top, and &quot;My Page&quot; plus &quot;I Want to Sell&quot; underneath. Simple and direct. The hard part was figuring out where to add AI features. At first I thought about making AI recommendations like a shopping platform, but &quot;cost-performance&quot; is too subjective, so I dropped it. I came up with a few more ideas, but none really held up. For a while, I was completely stuck.</p><p>Then I talked to a friend who loves digital gadgets, and one sentence suddenly cleared everything up: &quot;When people sell used items, they usually only say how long they&#39;ve used it, what flaws it has, and whether it still works. They don&#39;t list specs the way merchants do. What if AI helped novice buyers understand the product description instead of making them go hunt down the details themselves?&quot;</p><p>That was it. The direction became clear instantly. The AI feature should live inside the product description. Later, an intelligent pricing feature naturally followed.</p><p><img src="'+l+'" alt="The campus secondhand marketplace demo"></p><h2 id="_05-i-felt-like-the-worst-student-in-the-livestream-but-got-the-most-valuable-encouragement" tabindex="-1">05 I Felt Like the Worst Student in the Livestream, but Got the Most Valuable Encouragement <a class="header-anchor" href="#_05-i-felt-like-the-worst-student-in-the-livestream-but-got-the-most-valuable-encouragement" aria-label="Permalink to “05 I Felt Like the Worst Student in the Livestream, but Got the Most Valuable Encouragement”">​</a></h2><p>I put a lot of effort into the project, and by the time of the livestream, it was finally done. But the closer I got to presenting it, the more nervous I became. The projects shown before mine were all polished and refined, and every interaction looked smoother than the last. Before the event, I had felt confident. But when it was really my turn, the only thought left in my head was: &quot;There has to be room for bad students too.&quot;</p><p>So I took a deep breath and presented my demo, feeling both brave and uneasy. When it was over, my mind exploded with self-criticism: my questions had been dumb, my project wasn&#39;t polished, my idea was boring, and so many parts were still unfinished.</p><p>But to my surprise, the teachers did not dismiss me at all. Instead, they gave me a lot of specific, practical suggestions. That was the moment I realized that even something imperfect could still be taken seriously. Before this, I had almost never been given a chance to calmly present a project that was still immature.</p><p><img src="'+h+'" alt="Working on the project together with other builders"></p><h2 id="_06-what-i-gained-was-much-more-than-a-demo" tabindex="-1">06 What I Gained Was Much More Than a Demo <a class="header-anchor" href="#_06-what-i-gained-was-much-more-than-a-demo" aria-label="Permalink to “06 What I Gained Was Much More Than a Demo”">​</a></h2><p>Through this experience, I genuinely feel that my ability to solve real problems has improved. First, my learning efficiency went up. I learned how to build small tools for myself, such as an AI-powered schedule planner and a personal blog. Second, the way I learn changed. Instead of painfully chewing through thick tutorials page by page, I started directly designing my own small projects and learning by building.</p><p>Not knowing how to code is no longer fatal. AI can help write code. When I run into something I don&#39;t understand, I can ask directly: &quot;What does this line mean?&quot; &quot;What concept is this using?&quot; &quot;How do I fix this error?&quot;</p><p>With Trae, the wall between &quot;having an idea&quot; and &quot;making it real&quot; suddenly felt much lower. Even without a strong programming foundation, I could gradually turn ideas in my head into something tangible. Watching a product evolve through iteration gives me a very real sense of achievement.</p><p>This experience made me believe that the threshold for creating things may really be much lower than we once imagined.</p>',38)])])}const b=a(d,[["render",u]]);export{w as __pageData,b as default};
